-- SECURITY DEFINER; API roles that may call it: authenticated, service_role
CREATE OR REPLACE FUNCTION public.resnapshot_invoice(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare inv record; t record;
begin
  select * into inv from public.invoices where id = p_id;
  if inv is null or inv.reward_id is null then return; end if;
  if inv.stage in ('sent', 'paid') then return; end if;

  select * into t from public.invoice_terms(inv.reward_id);
  if t.payment is null or not public.invoice_is_payable(t.payment) then return; end if;

  update public.invoices
     set payment  = t.payment,
         currency = t.currency,
         amount   = t.amount,
         fx_rate  = t.fx,
         bill_to  = case when coalesce(bill_to, '') = ''
                         then coalesce((select value ->> 'text' from public.app_settings
                                         where key = 'invoice_bill_to'), '')
                         else bill_to end
   where id = p_id;
end $function$;
